/**
 * @summary List exam attempts for current user
 */
export const getListExamAttemptsUrl = (params?: ListExamAttemptsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/exams/attempts?${stringifiedParams}`
    : `/api/exams/attempts`;
};

export const listExamAttempts = async (
  params?: ListExamAttemptsParams,
  options?: RequestInit,
): Promise<ExamAttempt[]> => {
  return customFetch<ExamAttempt[]>(getListExamAttemptsUrl(params), {
    ...options,
    method: "GET",
  });
};

